package dev.rodrigo.locationlab;

import android.Manifest; import android.app.*; import android.content.*; import android.content.pm.PackageManager; import android.os.*; import android.widget.*; import androidx.activity.ComponentActivity; import androidx.activity.result.ActivityResultLauncher; import androidx.activity.result.contract.ActivityResultContracts; import androidx.core.content.ContextCompat; import com.google.android.gms.location.*; import java.util.*;

public class MainActivity extends ComponentActivity {
 private TextView status; private FusedLocationProviderClient fused; private GeofencingClient geofencing; private ActivityRecognitionClient activity; private PendingIntent geofencePi,activityPi;
 private final ActivityResultLauncher<String[]> permissionLauncher=registerForActivityResult(new ActivityResultContracts.RequestMultiplePermissions(),r->refreshLocation());
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);status=findViewById(R.id.status);fused=LocationServices.getFusedLocationProviderClient(this);geofencing=LocationServices.getGeofencingClient(this);activity=ActivityRecognition.getClient(this);geofencePi=PendingIntent.getBroadcast(this,10,new Intent(this,GeofenceReceiver.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_MUTABLE);activityPi=PendingIntent.getBroadcast(this,11,new Intent(this,ActivityReceiver.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_MUTABLE);findViewById(R.id.permissions).setOnClickListener(v->askPermissions());findViewById(R.id.location).setOnClickListener(v->refreshLocation());findViewById(R.id.geofence).setOnClickListener(v->addHereGeofence());findViewById(R.id.remove).setOnClickListener(v->removeGeofence());findViewById(R.id.activity_start).setOnClickListener(v->startActivityUpdates());findViewById(R.id.activity_stop).setOnClickListener(v->stopActivityUpdates());status.setText("Ready");}
 private boolean locationGranted(){return ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED;} private boolean activityGranted(){return Build.VERSION.SDK_INT<29||ContextCompat.checkSelfPermission(this,Manifest.permission.ACTIVITY_RECOGNITION)==PackageManager.PERMISSION_GRANTED;}
 private void askPermissions(){List<String> p=new ArrayList<>();p.add(Manifest.permission.ACCESS_FINE_LOCATION);p.add(Manifest.permission.ACCESS_COARSE_LOCATION);if(Build.VERSION.SDK_INT>=29)p.add(Manifest.permission.ACTIVITY_RECOGNITION);permissionLauncher.launch(p.toArray(new String[0]));}
 private void refreshLocation(){if(!locationGranted()){status.setText("Location permission required");return;}try{fused.getLastLocation().addOnSuccessListener(l->status.setText(l==null?"No cached location yet":"Last location: "+l.getLatitude()+", "+l.getLongitude())).addOnFailureListener(e->status.setText("Location error: "+e.getMessage()));}catch(SecurityException e){status.setText("Location permission denied");}}
 private void addHereGeofence(){if(!locationGranted()){status.setText("Location permission required");return;}try{fused.getLastLocation().addOnSuccessListener(l->{if(l==null){status.setText("No last location; acquire a fix first");return;}Geofence g=new Geofence.Builder().setRequestId("here-150m").setCircularRegion(l.getLatitude(),l.getLongitude(),150f).setTransitionTypes(Geofence.GEOFENCE_TRANSITION_ENTER|Geofence.GEOFENCE_TRANSITION_EXIT).setExpirationDuration(60*60*1000L).build();GeofencingRequest req=new GeofencingRequest.Builder().setInitialTrigger(GeofencingRequest.INITIAL_TRIGGER_ENTER).addGeofence(g).build();try{geofencing.addGeofences(req,geofencePi).addOnSuccessListener(v->status.setText("150 m geofence added. Background delivery may require Always location access.")).addOnFailureListener(e->status.setText("Geofence error: "+e.getMessage()));}catch(SecurityException e){status.setText("Location permission denied");}});}catch(SecurityException e){status.setText("Location permission denied");}}
 private void removeGeofence(){geofencing.removeGeofences(geofencePi).addOnCompleteListener(t->status.setText("Geofence removed"));}
 private void startActivityUpdates(){if(!activityGranted()){status.setText("Activity Recognition permission required");return;}try{activity.requestActivityUpdates(5000,activityPi).addOnSuccessListener(v->status.setText("Activity updates requested every ~5 s")).addOnFailureListener(e->status.setText("Activity error: "+e.getMessage()));}catch(SecurityException e){status.setText("Activity permission denied");}}
 private void stopActivityUpdates(){activity.removeActivityUpdates(activityPi).addOnCompleteListener(t->status.setText("Activity updates stopped"));}
}